 const chart=document.createElement('section');chart.className='panel chart-panel market-main-chart';chart.innerHTML=`<div class="panel-head"><div class="market-chart-title"><h3>${esc(coin.ticker)} · ${esc(coin.name)}</h3><select aria-label="Выбрать актив" id="chart-asset">${state.market.coins.map(c=>`<option value="${c.id}" ${c.id===state.coin?'selected':''}>${esc(c.ticker)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="timeframes">${[['1m','1м'],['5m','5м'],['15m','15м'],['1h','1ч'],['4h','4ч'],['1d','1д'],['1w','1н']].map(([key,label])=>`<button data-market-interval="${key}" class="${state.interval===key?'active':''}">${label}</button>`).join('')}<button data-market-zoom="in">＋</button><button data-market-zoom="out">－</button></div></div><div class="chart-wrap"><canvas id="market-chart" role="img" aria-label="График ${esc(coin.ticker)}"></canvas></div><div class="market-chart-foot"><span>${money(coin.price,Number(coin.price)<1?4:2)} <b class="${coin.change>=0?'up':'down'}">${coin.change>=0?'+':''}${Number(coin.change).toFixed(2)}%</b></span><span>Объём ${money(coin.volume,0)} · Капитализация ${money(coin.market_cap,0)}</span><button class="secondary" id="open-detail">Подробнее →</button></div>`;
