function setupMarketFilters(){const panel=$('.market-table')?.closest('.panel'),head=panel?.querySelector('.panel-head');if(!head)return;const bar=document.createElement('div');bar.className='asset-filters';const groups=[['all','Все активы'],['ru','Российские акции'],['global','Международные акции'],['token','Токены игроков']];for(const [key,label] of groups){const button=document.createElement('button');button.textContent=label;button.className=(state.marketFilter||'all')===key?'active':'';button.onclick=()=>{state.marketFilter=key;setupMarketFiltersUpdate();};bar.append(button);}head.after(bar);const tools=document.createElement('div');tools.className='market-tools';tools.innerHTML='<input id="asset-search" type="search" placeholder="Поиск по названию или тикеру" aria-label="Поиск активов"><select id="asset-sort" aria-label="Сортировать активы"><option value="default">По умолчанию</option><option value="price">Цена ↓</option><option value="change">Доходность ↓</option><option value="market_cap">Капитализация ↓</option><option value="volume">Объём ↓</option></select>';bar.after(tools);tools.querySelector('input').value=state.marketSearch||'';tools.querySelector('select').value=state.marketSort||'default';tools.querySelector('input').oninput=e=>{state.marketSearch=e.target.value;setupMarketFiltersUpdate();};tools.querySelector('select').onchange=e=>{state.marketSort=e.target.value;setupMarketFiltersUpdate();};setupMarketFiltersUpdate();}
function setupMarketFiltersUpdate(){document.querySelectorAll('.asset-filters button').forEach((b,i)=>b.classList.toggle('active',['all','ru','global','token'][i]===(state.marketFilter||'all')));const rows=[...document.querySelectorAll('.market-table [data-coin]')],tbody=rows[0]?.parentElement;rows.sort((a,b)=>{if(!state.marketSort||state.marketSort==='default')return 0;const ca=state.market.coins.find(c=>c.id===a.dataset.coin),cb=state.market.coins.find(c=>c.id===b.dataset.coin);return Number(cb?.[state.marketSort]||0)-Number(ca?.[state.marketSort]||0);});for(const row of rows){const coin=state.market.coins.find(c=>c.id===row.dataset.coin),match=(`${coin?.ticker} ${coin?.name}`).toLowerCase().includes((state.marketSearch||'').toLowerCase());row.hidden=!match||(state.marketFilter&&state.marketFilter!=='all'?(state.marketFilter==='token'?coin?.asset_kind!=='token':coin?.region!==state.marketFilter):false);tbody.append(row);}}
