function setupCreate2(){const form=$('#create-form');if(!form)return;const ticker=form.elements.ticker,liquidity=form.elements.liquidity,supply=form.elements.supply,button=form.querySelector('button[type=submit],button.primary');const preview=document.createElement('div');preview.className='trade-preview';button.before(preview);let check=0;const update=async()=>{const symbol=ticker.value.trim().toUpperCase(),liquid=Number(liquidity.value),issued=Number(supply.value),fee=Number(state.market.settings.listing_fee),balance=Number(state.wallet?.cash||0);let available=false;if(/^[A-Z0-9]{2,8}$/.test(symbol)){const seq=++check;try{const result=await api('/api/ticker/'+encodeURIComponent(symbol));if(seq!==check)return;available=result.available;}catch{}}else check++;preview.innerHTML=`<div><span>Тикер ${esc(symbol||'—')}</span><b class="${available?'up':'down'}">${available?'Свободен':'Недоступен'}</b></div><div><span>Стартовая цена</span><b>${liquid>0&&issued>0?money(liquid/(issued/2),8):'—'}</b></div><div><span>Листинг + ликвидность</span><b>${money(fee+liquid)}</b></div><div><span>Баланс после запуска</span><b class="${balance<fee+liquid?'down':''}">${money(balance-fee-liquid)}</b></div>`;button.disabled=!available||!Number.isSafeInteger(issued)||issued<100||liquid<100||balance<fee+liquid;};ticker.oninput=()=>{ticker.value=ticker.value.toUpperCase();update();};liquidity.oninput=update;supply.oninput=update;update();form.onsubmit=async e=>{e.preventDefault();if(button.disabled)return;const data=Object.fromEntries(new FormData(form));if(!window.confirm(`Создать ${data.ticker} за ${money(Number(state.market.settings.listing_fee)+Number(data.liquidity))}?`))return;button.disabled=true;try{const coin=await api('/api/tokens',{method:'POST',body:JSON.stringify(data)});state.coin=coin.id;state.page='detail';await refresh();toast(`Токен ${coin.ticker} создан`);}catch(err){toast(err.message,true);update();}};}
function setupWallet2(){const w=state.wallet;if(!w)return;const cards=$('.cards');if(!cards)return;cards.insertAdjacentHTML('beforeend',`<div class="panel metric"><small>Прибыль за 24 часа</small><strong class="${Number(w.profit24h||0)>=0?'up':'down'}">${w.profit24h===null?'—':money(w.profit24h)}</strong></div><div class="panel metric"><small>Прибыль за всё время</small><strong class="${Number(w.profitAll)>=0?'up':'down'}">${money(w.profitAll)}</strong></div>`);const charts=document.createElement('div');charts.className='wallet-charts section';const total=Number(w.total)||1,colors=['#b7f763','#6dc9c2','#f0c96f','#9d8bda','#ff7474'];let offset=0;const segments=w.holdings.slice(0,5).map((h,i)=>{const percent=Math.max(0,Number(h.amount)*Number(h.price)/total*100),start=offset;offset+=percent;return `${colors[i]} ${start}% ${offset}%`;});segments.push(`#293238 ${offset}% 100%`);charts.innerHTML=`<section class="panel"><div class="panel-head"><h3>История капитала</h3></div><div class="wallet-chart-wrap"><canvas id="portfolio-chart" role="img" aria-label="История капитала"></canvas></div></section><section class="panel"><div class="panel-head"><h3>Распределение портфеля</h3></div><div class="allocation"><div class="allocation-ring" style="background:conic-gradient(${segments.join(',')})"></div><div>${w.holdings.slice(0,5).map((h,i)=>`<div class="allocation-item"><i style="background:${colors[i]}"></i>${esc(h.ticker)} <b>${(Number(h.amount)*Number(h.price)/total*100).toFixed(1)}%</b></div>`).join('')}<div class="allocation-item"><i style="background:#293238"></i>Игровые $ <b>${(Number(w.cash)/total*100).toFixed(1)}%</b></div></div></div></section>`;cards.after(charts);drawPortfolioChart(w.history);const table=$('.market-table');if(table){table.querySelector('thead tr').insertAdjacentHTML('beforeend','<th>Средняя покупка</th><th>Прибыль / убыток</th>');for(const row of table.querySelectorAll('tbody tr[data-coin]')){const h=w.holdings.find(x=>x.coin_id===row.dataset.coin);if(!h)continue;const pnl=h.cost_basis===null?null:(Number(h.price)-Number(h.cost_basis))*Number(h.amount);row.insertAdjacentHTML('beforeend',`<td>${h.cost_basis===null?'—':money(h.cost_basis,4)}</td><td class="${Number(pnl||0)>=0?'up':'down'}">${pnl===null?'—':money(pnl)}</td>`);}}const history=$('.content > section.panel.section:last-of-type');if(history){const search=document.createElement('input');search.type='search';search.className='history-search';search.placeholder='Поиск по операциям';history.querySelector('.panel-head').append(search);search.oninput=()=>history.querySelectorAll('.news-item').forEach(item=>item.hidden=!item.textContent.toLowerCase().includes(search.value.toLowerCase()));}if(w.alerts?.length){const active=w.alerts.filter(a=>!a.triggered_at);const alertPanel=document.createElement('section');alertPanel.className='panel section';alertPanel.innerHTML=`<div class="panel-head"><h3>Ценовые уведомления</h3><small>${active.length} активных</small></div>${w.alerts.slice(0,10).map(a=>`<div class="news-item">${esc(a.ticker)} · ${a.direction==='up'?'выше':'ниже'} ${money(a.target,4)} · ${a.triggered_at?'Сработало':'Ожидает'}</div>`).join('')}`;$('.content').append(alertPanel);}}
function drawPortfolioChart(history){const canvas=$('#portfolio-chart');if(!canvas)return;const dpr=devicePixelRatio||1,ctx=canvas.getContext('2d'),w=canvas.width=Math.max(280,canvas.clientWidth*dpr),h=canvas.height=Math.max(150,canvas.clientHeight*dpr),values=(history||[]).map(x=>Number(x.total));if(!values.length)return;const low=Math.min(...values),high=Math.max(...values),span=high-low||1;ctx.strokeStyle='#b7f763';ctx.lineWidth=2*dpr;ctx.beginPath();values.forEach((v,i)=>{const x=20*dpr+i/Math.max(1,values.length-1)*(w-40*dpr),y=h-20*dpr-(v-low)/span*(h-40*dpr);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});if(values.length===1)ctx.lineTo(w-20*dpr,h/2);ctx.stroke();}
